SELECT * FROM appointment WHERE user_id=#{userId} AND schedule_id=#{scheduleId}
AND patient_name=#{name} AND patient_phone=#{phone} AND status <> 'cancelled'
ORDER BY id FOR UPDATE

SELECT id,type,amount,balance_after,order_id,pay_method,remark,create_time
FROM balance_log WHERE user_id=#{userId}
AND type=#{type}
ORDER BY create_time DESC,id DESC
